'use strict';
(() => {
const KEY='teb-standalone-v1', SESSION='teb-standalone-session-v1';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>JSON.parse(JSON.stringify(v));
const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const localDate=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const today=()=>localDate(new Date());
const dateOf=s=>new Date(s+'T12:00:00');
const fmt=(s,opt={day:'numeric',month:'long'})=>dateOf(s).toLocaleDateString('da-DK',opt);
const monthText=d=>d.toLocaleDateString('da-DK',{month:'long',year:'numeric'});
const monthStart=d=>new Date(d.getFullYear(),d.getMonth(),1,12);
const monthEnd=d=>new Date(d.getFullYear(),d.getMonth()+1,0,12);
const shiftMonth=(d,n)=>new Date(d.getFullYear(),d.getMonth()+n,1,12);
const weekStart=d=>{const n=new Date(d);n.setDate(n.getDate()-((n.getDay()+6)%7));return n;};
const addDays=(d,n)=>{const a=new Date(d);a.setDate(a.getDate()+n);return a;};
const button=(text,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,path,cls='')=>`<a class="btn ${cls}" href="#${path}">${text}</a>`;
const external=(text,url)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`;
const statusTag=s=>`<span class="tag ${esc(s)}">${({published:'Offentligt',pending:'Afventer TEB',cancelled:'Aflyst',rejected:'Afvist',invited:'Inviteret'})[s]||esc(s)}</span>`;
function seed(){
 const base=monthStart(new Date());const stamp=new Date(base.getFullYear(),base.getMonth()-3,1,10).toISOString();
 const associations=[
  {id:'motion',name:'Tistrup Motion & Fællesskab',category:'Motion',initials:'TM',description:'Vi mødes om bevægelse, frisk luft og gode snakke. Her er plads til både rolige gåture og lidt mere fart på cyklen.',chair:'Anna Jensen',email:'kontakt@motion.example',phone:'12 34 56 78',website:'',place:'Hodde-Tistrup Hallen'},
  {id:'kultur',name:'Kulturvennerne i Tistrup',category:'Kultur',initials:'KT',description:'Koncerter, fællessang og foredrag tæt på, hvor vi bor. Vi skaber små og store kulturoplevelser for hele byen.',chair:'Peter Nielsen',email:'kontakt@kultur.example',phone:'12 34 56 79',website:'',place:'Kulturhuset'},
  {id:'spejder',name:'Tistrup Naturspejdere',category:'Børn og unge',initials:'TN',description:'Bål, udeliv og oplevelser sammen. Vi tager på ture og lærer naturen at kende med plads til nysgerrighed.',chair:'Sofie Madsen',email:'kontakt@spejder.example',phone:'12 34 56 80',website:'',place:'Spejderhuset'},
  {id:'senior',name:'Tistrup Seniorklub',category:'Samvær',initials:'TS',description:'Et fællesskab om eftermiddagskaffe, banko, ture og hyggelige stunder. Nye ansigter er altid velkomne.',chair:'Jens Sørensen',email:'kontakt@senior.example',phone:'12 34 56 81',website:'',place:'Hodde-Tistrup Hallen'},
  {id:'hodde',name:'Hodde Landsbyfællesskab',category:'Lokalsamfund',initials:'HL',description:'Vi samler naboerne om fællesspisning, praktiske projekter og livet i Hodde. Kom med, når du har tid og lyst.',chair:'Lene Pedersen',email:'kontakt@hodde.example',phone:'12 34 56 82',website:'',place:'Hodde Forsamlingshus'},
  {id:'kreativ',name:'Det kreative værksted',category:'Kultur',initials:'KV',description:'For dig, der holder af at skabe noget med hænderne. Vi mødes om håndarbejde, reparationer og nye idéer.',chair:'Mette Andersen',email:'kontakt@kreativ.example',phone:'12 34 56 83',website:'',place:'Kulturhuset'}
 ];
 const titles=['Morgentur med kaffe bagefter','Fællessang i Kulturhuset','Kom og prøv spejderlivet','Banko og eftermiddagskaffe','Fællesspisning i Hodde','Åbent kreativt værksted','Cykeltur ud i det blå','Musik og en kop kaffe','Efterårshygge ved bålet','Foredrag og fællesskab','Suppeaften for hele familien','Reparér og giv nyt liv'];
 const days=[3,5,7,10,12,15,18,20,22,24,27,29];const events=[];
 for(let m=-1;m<=2;m++)for(let i=0;i<titles.length;i++){
  const a=associations[i%6],d=new Date(base.getFullYear(),base.getMonth()+m,Math.min(days[i],monthEnd(shiftMonth(base,m)).getDate()),12);
  const item={id:'demo-'+m+'-'+i,title:titles[i],associationId:a.id,association:a.name,date:localDate(d),time:['09:00','19:00','17:00','14:00','18:00','13:30'][i%6],endDate:'',endTime:'',location:a.place,description:['Vi mødes foran hallen og går en tur i et roligt tempo. Alle er velkomne. Tag gerne en nabo med.','En hyggelig stund sammen med andre fra byen. Ingen særlige forudsætninger, bare lysten til at være med.'][i%2],price:i%3===0?'Gratis':'Se praktisk info i beskrivelsen',url:'',status:'published'};
  events.push({...item,contactEmail:'anna@forening.example',ownerEmail:i%6===0?'anna@forening.example':a.email,createdAt:stamp,history:[{at:stamp,data:clone(item)}],pending:null});
 }
 const pending={id:'guest-example',title:'Loppemarked i forsamlingshuset',association:'Nabogruppen',associationId:null,date:localDate(addDays(base,25)),time:'10:00',endDate:'',endTime:'14:00',location:'Hodde Forsamlingshus',description:'Kom og gør et fund. Der er kaffe på kanden og god plads til at møde naboerne.',price:'Fri entré',url:'',status:'pending'};
 events.push({...pending,ownerEmail:'nabo@example.org',contactEmail:'nabo@example.org',manageToken:'demo-guest-key',createdAt:stamp,history:[],pending:{kind:'create',data:clone(pending)},moderationNote:''});
 const editionStart=localDate(base),editionEnd=localDate(monthEnd(shiftMonth(base,1)));
 return {version:1,associations,events,memberships:[{email:'anna@forening.example',name:'Anna Jensen',associationId:'motion',role:'manager',status:'active'},{email:'mikkel@forening.example',name:'Mikkel Hansen',associationId:'motion',role:'editor',status:'active'},{email:'peter@forening.example',name:'Peter Nielsen',associationId:'kultur',role:'manager',status:'active'}],requests:[],editions:[{id:'demo-edition',start:editionStart,end:editionEnd,deadline:today(),createdAt:stamp,events:events.filter(e=>e.status==='published'&&e.date>=editionStart&&e.date<=editionEnd).map(publicData)}]};
}
function read(key,fallback){try{const data=JSON.parse(localStorage.getItem(key));return data??fallback;}catch{return fallback;}}
let db=read(KEY,null);if(!db||db.version!==1)db=seed();
let session=read(SESSION,null),shownMonth=monthStart(new Date()),shownWeek=weekStart(new Date()),calendarMode='month',filterCategory='',filterText='',draftEdition=null,loginEmail='',loginRequestedAt=0,lastFocus=null;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('Browseren kunne ikke gemme. Ændringerne virker indtil siden lukkes.');}}
function setSession(value){session=value;try{localStorage.setItem(SESSION,JSON.stringify(value));}catch{} }
function publicData(e){return Object.fromEntries(['id','title','associationId','association','date','time','endDate','endTime','location','description','price','url','status'].map(k=>[k,e[k]??'']));}
function association(id){return db.associations.find(a=>a.id===id);}
function myMemberships(){return session?db.memberships.filter(m=>m.email===session.email&&m.status==='active'):[];}
function isTeb(){return session?.email==='teb@prototype.example';}
function canManageAssociation(id){return isTeb()||myMemberships().some(m=>m.associationId===id&&m.role==='manager');}
function canEdit(e){return isTeb()||myMemberships().some(m=>m.associationId===e.associationId);}
function canGuestEdit(e,key){return !!e?.manageToken&&e.manageToken===key;}
function published(){return db.events.filter(e=>e.status==='published'||e.status==='cancelled');}
function currentPath(){return (location.hash.slice(1)||'forening').split('/');}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
function toast(message){const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,4200);}
function openModal(title,content){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="modal-close" type="button" data-action="close-modal" aria-label="Luk vinduet">×</button></div>${content}</section></div>`;requestAnimationFrame(()=>$('.modal input,.modal button')?.focus());}
function closeModal(){if(!$('#modal-root').firstChild)return;$('#modal-root').innerHTML='';lastFocus?.focus?.();}
function actionConfirm(title,text,action,extra=''){openModal(title,`<p>${text}</p><div class="actions">${button('Ja, fortsæt',action,extra,'primary')}${button('Fortryd','close-modal')}</div>`);}
function pageHero(kicker,title,description,aside=''){return `<section class="hero"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${aside?`<aside class="hero-aside">${aside}</aside>`:''}</section>`;}
function channels(compact=false){const entries=[['Flyers i postkasserne','Få jeres arrangement med på en flyer eller i en lokal omdeling.','Omdeling og flyers'],['Byportaler og infoskærme','Bliv set på de analoge byportaler eller på lokale og kommunale skærme.','Byportaler og infoskærme'],['Opslag rundt i byen','Find muligheder for plakater på opslagstavler og andre aftalte steder.','Plakater og opslag'],['Lokale medier og Facebook','Send et tip til de lokale medier, eller del arrangementet på jeres egen Facebook-side.','Medier og Facebook']];return `<section class="section" id="del-flere-steder"><div class="eyebrow">Når I gerne vil nå flere</div><h2>Giv arrangementet lidt mere liv.</h2><p class="muted">Kalenderen er én mulighed. Her er flere veje ud i byen. I kontakter selv udbyderen.</p><div class="channels">${entries.slice(0,compact?2:4).map((c,i)=>`<article class="channel"><div class="num">0${i+1}</div><h3>${c[0]}</h3><p>${c[1]}</p>${button('Se muligheder →','channel',`data-channel="${esc(c[2])}"`,'soft small')}</article>`).join('')}</div><p class="source-note">Konkrete kontakter, priser og aftaler tilføjes sammen med TEB. Der er ingen automatisk deling til andre kanaler.</p></section>`;}
function renderDirectory(){return pageHero('Foreningsliv i Tistrup og Hodde','Find dit <em>fællesskab.</em>','Mød byens foreninger, og find nogen at dele din interesse med.',`<p>Er du med til at drive en forening?</p>${session?link(isTeb()?'Åbn TEBs arbejdsområde':'Åbn min forening',isTeb()?'forening/teb':'forening/min'):button('Log ind for din forening','login','','primary')}`)+`<div class="filters"><label>Søg efter en forening<input type="search" id="association-search" placeholder="Navn eller interesse" value="${esc(filterText)}"></label><label>Interesse<select id="association-category"><option value="">Alle interesser</option>${[...new Set(db.associations.map(a=>a.category))].sort().map(c=>`<option ${c===filterCategory?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div id="association-results">${directoryCards()}</div><div class="callout"><div><h3>Skal jeres forening også være med?</h3><p>Få en profil, som I selv kan holde opdateret. TEB hjælper jer i gang.</p></div>${button('Få adgang','request-access','','soft')}</div>`;}
function directoryCards(){const rows=db.associations.filter(a=>(!filterCategory||a.category===filterCategory)&&(!filterText||(a.name+' '+a.description+' '+a.category).toLocaleLowerCase('da').includes(filterText.toLocaleLowerCase('da'))));return `<p class="small muted">${rows.length} forening${rows.length===1?'':'er'} · Eksempeloversigt</p><div class="grid3">${rows.map(a=>`<a class="association-card" href="#forening/profil/${a.id}"><div class="association-top"><span class="monogram">${esc(a.initials)}</span><span class="tag">${esc(a.category)}</span></div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><div class="card-bottom"><span>Formand · ${esc(a.chair)}</span><span aria-hidden="true">↗</span></div></a>`).join('')}</div>${rows.length?'':'<div class="empty">Ingen foreninger matcher din søgning. Prøv et andet ord.</div>'}`;}
function renderProfile(id){const a=association(id);if(!a)return notFound();const events=published().filter(e=>e.associationId===id&&e.date>=today()&&e.status!=='cancelled');return `<p class="breadcrumbs"><a href="#forening">← Alle foreninger</a></p>`+pageHero(esc(a.category),esc(a.name),'En del af foreningslivet i Tistrup og Hodde.')+`<div class="profile-layout"><section><h2>Om foreningen</h2><p>${esc(a.description)}</p><div class="contact-block"><h3>Find os</h3><p>${esc(a.place||'Kontakt foreningen for at høre mere.')}</p>${a.website?external('Besøg hjemmesiden',a.website):''}</div></section><aside class="form-panel"><h3>Kontakt foreningen</h3><p><span class="muted small">Formand</span><br>${esc(a.chair)}</p><p><span class="muted small">E-mail</span><br><a href="mailto:${esc(a.email)}">${esc(a.email)}</a></p><p><span class="muted small">Telefon</span><br>${esc(a.phone||'Ikke oplyst')}</p><p class="note">Kontaktoplysningerne er eksempeldata.</p></aside></div><section class="section" style="margin-top:40px"><h2>Det har vi på programmet</h2>${events.length?events.sort(sortEvents).map(agendaRow).join(''):'<p class="muted">Der er ingen kommende arrangementer endnu.</p>'}</section>`;}
function renderWorkspace(tab='events'){
 if(!session)return loginRequired();if(isTeb())return renderAdmin(tab==='events'?'pending':tab);
 const members=myMemberships();if(!members.length)return pageHero('Min forening','Velkommen.','Din e-mail er bekræftet. TEB skal knytte dig til en forening, før du kan redigere eller udgive.')+renderAccessRequest();
 const aid=read('teb-demo-selected-association',members[0].associationId),a=association(members.some(m=>m.associationId===aid)?aid:members[0].associationId);const manager=canManageAssociation(a.id);
 let content='';
 if(tab==='profile')content=`<div class="profile-layout"><form id="profile-form" class="form-panel form-stack" data-id="${a.id}"><label>Foreningens navn<input name="name" maxlength="100" value="${esc(a.name)}" required></label><label>Kort om foreningen<textarea name="description" maxlength="800" required>${esc(a.description)}</textarea></label><div class="form-row"><label>Formand<input name="chair" value="${esc(a.chair)}" required></label><label>Interesse<select name="category">${['Motion','Kultur','Børn og unge','Samvær','Lokalsamfund','Andet'].map(c=>`<option ${a.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="form-row"><label>Offentlig kontaktmail<input name="email" type="email" value="${esc(a.email)}" required></label><label>Offentligt telefonnummer<input name="phone" type="tel" value="${esc(a.phone)}"></label></div><label>Mødested<input name="place" value="${esc(a.place)}"></label><label>Hjemmeside <span class="muted">valgfrit</span><input name="website" type="url" value="${esc(a.website)}" placeholder="https://"></label><button class="btn primary" type="submit">Gem oplysninger</button></form><aside><h3>Det kan borgerne se</h3><p class="muted">Oplysningerne her vises på jeres offentlige profil. Personer med login vises kun for jer.</p>${link('Se vores offentlige profil','forening/profil/'+a.id)}</aside></div>`;
 else if(tab==='access')content=`<h2>Personer med adgang</h2><p class="muted">Formanden på profilen og personer med login behøver ikke være de samme.</p><div class="access-list">${db.memberships.filter(m=>m.associationId===a.id).map(m=>`<div class="list-row"><div><strong>${esc(m.name||m.email)}</strong><p>${esc(m.email)} · ${m.role==='manager'?'Foreningsansvarlig':'Redaktør'} ${m.status==='invited'?statusTag('invited'):''}</p></div>${manager&&m.email!==session.email&&m.role!=='manager'?button('Fjern adgang','remove-access',`data-email="${esc(m.email)}" data-association="${a.id}"`,'small danger'):''}</div>`).join('')}</div>${manager?`<form id="invite-form" class="form-panel form-stack" data-id="${a.id}"><h3>Invitér en person</h3><div class="form-row"><label>Navn<input name="name" required maxlength="80"></label><label>E-mail<input name="email" type="email" required></label></div><p class="note">Personen bliver redaktør og kan opdatere profilen og udgive arrangementer for foreningen.</p><button type="submit" class="btn primary">Send invitation</button></form>`:'<p class="info-box">Den foreningsansvarlige kan invitere og fjerne personer.</p>'}`;
 else {const mine=db.events.filter(e=>e.associationId===a.id).sort(sortEvents);content=`<div class="section-heading"><h2>Vores arrangementer</h2>${link('Opret nyt arrangement +','kalender/opret','primary')}</div>${mine.length?mine.map(e=>`<article class="list-row"><div>${statusTag(e.status)}<h3 style="margin-top:9px">${esc(e.title)}</h3><p>${fmt(e.date)} · ${esc(e.time)} · ${esc(e.location)}</p></div><div class="actions">${link('Se','kalender/arrangement/'+e.id,'small')}${e.status==='published'?link('Ret','kalender/ret/'+e.id,'small')+button('Aflys','cancel-event',`data-id="${e.id}"`,'small danger'):''}</div></article>`).join(''):'<div class="empty">Opret jeres første arrangement, så det kommer med i kalenderen.</div>'}`;}
 return pageHero('Min forening',esc(a.name),`Du er logget ind som ${esc(session.email)}.`,members.length>1?`<label>Vælg forening<select id="workspace-association">${members.map(m=>`<option value="${m.associationId}" ${m.associationId===a.id?'selected':''}>${esc(association(m.associationId).name)}</option>`).join('')}</select></label>`:link('Se offentlig profil','forening/profil/'+a.id))+`<nav class="workspace-nav" aria-label="Min forening">${[['events','Arrangementer'],['profile','Oplysninger'],['access','Personer med adgang']].map(([key,text])=>`<a class="${tab===key?'active':''}" href="#forening/min/${key}">${text}</a>`).join('')}</nav>${content}`;
}
function sortEvents(a,b){return a.date.localeCompare(b.date)||a.time.localeCompare(b.time)||a.title.localeCompare(b.title,'da');}
function agendaRow(e){return `<article class="agenda-item"><div class="date-tile"><strong>${dateOf(e.date).getDate()}</strong><span>${fmt(e.date,{month:'short'})}</span></div><div><h3><a href="#kalender/arrangement/${e.id}">${esc(e.title)}</a></h3><p>${e.status==='cancelled'?statusTag('cancelled')+' ':''}${esc(e.time)} · ${esc(e.location)}</p><p>${esc(e.association)}</p></div>${link('Se mere','kalender/arrangement/'+e.id,'soft small')}</article>`;}
function eventsOn(day){return published().filter(e=>e.date<=day&&(e.endDate||e.date)>=day).sort(sortEvents);}
function calendarContent(){
 const current=calendarMode==='month'?shownMonth:shownWeek;const label=calendarMode==='month'?monthText(current):`${fmt(localDate(current),{day:'numeric',month:'short'})} til ${fmt(localDate(addDays(current,6)),{day:'numeric',month:'short'})}`;
 let content='';
 if(calendarMode==='month'){
 const start=weekStart(shownMonth),count=Math.ceil((((shownMonth.getDay()+6)%7)+monthEnd(shownMonth).getDate())/7)*7;
 content=`<div class="month-grid" role="group" aria-label="${esc(label)}">${['Mandag','Tirsdag','Onsdag','Torsdag','Fredag','Lørdag','Søndag'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:count},(_,i)=>{const date=addDays(start,i),ds=localDate(date);return `<div class="day ${date.getMonth()!==shownMonth.getMonth()?'outside':''} ${ds===today()?'today':''}"><span class="day-number">${date.getDate()}</span>${eventsOn(ds).map(e=>`<button class="day-event ${e.status==='cancelled'?'cancelled':''}" type="button" data-action="open-event" data-id="${e.id}"><strong>${esc(e.time)}${e.status==='cancelled'?' · Aflyst':''}</strong>${esc(e.title)}</button>`).join('')}</div>`;}).join('')}</div><div class="mobile-agenda">${monthAgenda()}</div>`;
 }else{const rows=published().filter(e=>e.date<=localDate(addDays(shownWeek,6))&&(e.endDate||e.date)>=localDate(shownWeek)).sort(sortEvents);content=rows.length?rows.map(agendaRow).join(''):'<div class="empty">Der er ingen arrangementer i denne uge. Prøv næste uge.</div>';}
 return `<div class="calendar-toolbar"><div class="month-controls">${button('‹','calendar-prev','aria-label="Forrige periode"','soft icon-btn')}<h2>${esc(label)}</h2>${button('›','calendar-next','aria-label="Næste periode"','soft icon-btn')}</div><div class="actions">${button('I dag','calendar-today','','soft')}<div class="segmented" aria-label="Kalendervisning"><button type="button" data-action="calendar-month" class="${calendarMode==='month'?'active':''}" aria-pressed="${calendarMode==='month'}">Måned</button><button type="button" data-action="calendar-week" class="${calendarMode==='week'?'active':''}" aria-pressed="${calendarMode==='week'}">Uge</button></div></div></div>${content}<div class="calendar-legend"><span>Tryk på et arrangement for at se mere.</span><span>Seneste nyt findes altid digitalt.</span></div>`;
}
function monthAgenda(){const end=monthEnd(shownMonth);const items=published().filter(e=>e.date<=localDate(end)&&(e.endDate||e.date)>=localDate(shownMonth)).sort(sortEvents);let last='';return items.length?items.map(e=>{const start=localDate(weekStart(dateOf(e.date)));const title=start!==last?`<div class="week-title">${fmt(start,{day:'numeric',month:'short'})} til ${fmt(localDate(addDays(dateOf(start),6)),{day:'numeric',month:'short'})}</div>`:'';last=start;return title+agendaRow(e);}).join(''):'<div class="empty">Ingen arrangementer i denne måned endnu.</div>';}
function renderCalendar(){return pageHero('TEBs aktivitetskalender','Noget at <em>glæde sig til.</em>','Det lokale liv, samlet ét sted. Find dit næste arrangement i Tistrup og Hodde.',`${link('Opret arrangement +','kalender/opret','primary')}<p style="margin-top:12px">${myMemberships().length?'Jeres forening kan udgive med det samme.':'Alle kan indsende. TEB godkender, før det bliver synligt.'}</p>`)+`<section id="calendar-content">${calendarContent()}</section><section class="section" id="printarkiv"><div class="section-heading"><div><div class="eyebrow">Til opslagstavlen</div><h2>Kalenderen på papir.</h2></div>${isTeb()?link('Lav en printudgave','forening/teb/print','soft'):''}</div><p class="muted">Hent en udgave til væggen. Perioder og frister fremgår af hver udgave. Senere ændringer findes i den digitale kalender.</p><div class="edition-list">${db.editions.slice().reverse().map(e=>`<article class="edition-card"><div class="eyebrow">Prøveudgave</div><h3>${esc(editionTitle(e))}</h3><p>${e.events.length} arrangementer · Indhold pr. ${fmt(e.deadline)}</p>${link('Åbn print / gem som PDF','kalender/print/'+e.id,'soft small')}</article>`).join('')}</div></section>${channels()}`;}
function editionTitle(e){if(e.start===localDate(monthStart(dateOf(e.start)))&&e.end===localDate(monthEnd(dateOf(e.end)))){if(e.start.slice(0,7)===e.end.slice(0,7))return fmt(e.start,{month:'long',year:'numeric'});return `${fmt(e.start,e.start.slice(0,4)===e.end.slice(0,4)?{month:'long'}:{month:'long',year:'numeric'})} til ${fmt(e.end,{month:'long',year:'numeric'})}`;}return `${fmt(e.start,{day:'numeric',month:'long',year:'numeric'})} til ${fmt(e.end,{day:'numeric',month:'long',year:'numeric'})}`;}
function renderEvent(id){const e=db.events.find(x=>x.id===id);if(!e||!['published','cancelled'].includes(e.status))return notFound();return `<p class="breadcrumbs"><a href="#kalender">← Til kalenderen</a></p>`+pageHero(esc(e.association),esc(e.title),`${fmt(e.date,{weekday:'long',day:'numeric',month:'long',year:'numeric'})} · kl. ${esc(e.time)}`)+`<div class="profile-layout"><section>${e.status==='cancelled'?'<p class="info-box">Arrangementet er aflyst.</p>':''}<p style="white-space:pre-line">${esc(e.description)}</p>${e.url?external('Tilmelding og flere oplysninger',e.url):''}<div class="actions" style="margin-top:28px">${button('Kopiér link','copy-link')}${button('Gem i min kalender','download-ics',`data-id="${e.id}"`)}${canEdit(e)&&e.status==='published'?link('Ret arrangement','kalender/ret/'+e.id):''}</div></section><aside class="form-panel"><h3>Det praktiske</h3><p><strong>Sted</strong><br>${esc(e.location)}</p><p><strong>Tid</strong><br>${esc(e.time)}${e.endTime?' til '+esc(e.endTime):''}${e.endDate?' · Slutter '+fmt(e.endDate):''}</p><p><strong>Pris</strong><br>${esc(e.price||'Ikke oplyst')}</p><p class="note">Arrangeret af ${esc(e.association)}.</p>${e.associationId?`<a href="#forening/profil/${e.associationId}">Se foreningen →</a>`:''}</aside></div>`;}
function renderExternal(){const links=[['Pulsen i Vest','Arrangementer, oplevelser og lokale historier i hele området.','https://pulsenivest.dk/by/tistrup'],['Tistrup Nyt','Lokale nyheder og en kalender for Tistrup og Hodde.','https://tistrupnyt.dk/'],['Tistrupnews','Nyheder, foreningsliv og historier fra lokalområdet.','https://www.tistrupnews.dk/'],['VORES Tistrup','Lokale nyheder og indblik i livet omkring os.','https://vores-tistrup.dk/'],['Fællesskaber i Varde','Find fællesskaber og tilbud gennem Varde Kommunes oversigt.','https://sundhedsfremme.vardekommune.dk/lokalsamfund/']];return pageHero('Nyheder og oplevelser omkring os','Følg med i <em>det lokale liv.</em>','Her finder du vej til lokale medier og andres arrangementer. Hver side har sit eget indhold.')+`<div class="external-list">${links.map(l=>`<a class="external-link" href="${l[2]}" target="_blank" rel="noopener noreferrer"><div><strong>${l[0]}</strong><p>${l[1]}</p></div><span aria-hidden="true">↗</span></a>`).join('')}</div><section class="section" style="margin-top:35px"><div class="section-heading"><div><div class="eyebrow">Fra TEB</div><h2>Små glimt fra byen.</h2></div>${external('Følg TEB på Facebook','https://www.facebook.com/p/Tistrup-Erhvervs-og-Borgerforening-61594168058446/')}</div><div class="facebook-example"><p class="small muted">Eksempel på et Facebook-opslag · TEB</p><h3>Vi skaber byen sammen.</h3><p>Tak til alle, der møder op, giver en hånd og får noget til at ske. Her vil vores seneste Facebook-opslag blive vist.</p><p class="note">Prototypen henter ikke liveopslag fra Facebook.</p></div></section>`;}
function loginRequired(){return pageHero('Foreningsadgang','Log ind for at fortsætte.','Brug din e-mailadresse. Du behøver ikke huske en adgangskode.',button('Log ind','login','','primary'));}
function renderEventForm(id='',key=''){
 const old=id?db.events.find(e=>e.id===id):null;if(id&&(!old||(!canEdit(old)&&!canGuestEdit(old,key))))return notFound();if(old?.status==='cancelled')return notFound();
 const members=myMemberships(),direct=isTeb()||members.length>0;const selected=read('teb-demo-selected-association',members[0]?.associationId);
 const initial=old?.pending?.data||old||{title:'',date:today(),time:'',endDate:'',endTime:'',location:'',description:'',price:'',url:'',associationId:selected,association:'',contactEmail:session?.email||''};
 const assocs=isTeb()?db.associations:members.map(m=>association(m.associationId));
 const field=(label,name,type='text',required=true)=>`<label>${label}${required?'':' <span class="muted">valgfrit</span>'}<input type="${type}" name="${name}" value="${esc(initial[name]||'')}" ${required?'required':''} ${type==='text'?'maxlength="150"':''}></label>`;
 const associationField=direct?`<label>Forening<select name="associationId" id="event-association">${isTeb()?`<option value="" ${!initial.associationId?'selected':''}>Anden arrangør</option>`:''}${assocs.map(a=>`<option value="${a.id}" ${a.id===initial.associationId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>${isTeb()?`<label id="other-organizer" ${initial.associationId?'hidden':''}>Arrangørens navn<input name="association" value="${esc(initial.association)}" maxlength="100"></label>`:''}`:`<label>Forening eller arrangør<input name="association" list="association-names" value="${esc(initial.association)}" required maxlength="100"></label><datalist id="association-names">${db.associations.map(a=>`<option value="${esc(a.name)}">`).join('')}</datalist>`;
 return `<p class="breadcrumbs"><a href="#kalender">← Til kalenderen</a></p>`+pageHero('Del noget med byen',id?'Ret arrangementet.':'Hvad skal der <em>ske?</em>',direct?'Du udgiver på vegne af din forening. Arrangementet bliver synligt med det samme.':'Udfyld det vigtigste. TEB får besked og godkender, før arrangementet bliver synligt.')+`<div class="event-workspace"><form id="event-form" class="form-panel form-stack" data-id="${esc(id)}" data-key="${esc(key)}">${field('Arrangementets navn','title')}${associationField}<div class="form-row">${field('Dato','date','date')}${field('Klokken','time','time')}</div>${field('Sted','location')}<label>Lidt om arrangementet<textarea name="description" maxlength="1500" placeholder="Hvem er det for, og hvad skal man vide?">${esc(initial.description)}</textarea></label>${field('Pris eller fri entré','price','text',false)}<details><summary>Tilføj sluttid, flere dage eller tilmeldingslink</summary><div class="form-stack" style="margin-top:18px"><div class="form-row">${field('Slutdato','endDate','date',false)}${field('Sluttid','endTime','time',false)}</div>${field('Tilmeldingslink','url','url',false)}</div></details>${direct?'':`<label>Din e-mail<input name="contactEmail" type="email" value="${esc(old?.contactEmail||session?.email||'')}" required><span class="note">Bruges til kontakt om arrangementet. Vises ikke offentligt.</span></label>`}<div id="event-error" class="form-error" role="alert"></div><button class="btn primary" type="submit">${direct?(id?'Gem og udgiv ændringer':'Udgiv arrangement'):(id?'Send ændringer til TEB':'Send til TEBs godkendelse')}</button><p class="note">${direct?'Du kan rette eller aflyse igen fra din foreningsside.':'Du får et privat link til status og rettelser. Mailen simuleres i prototypen.'}</p></form><aside class="preview-panel"><p class="preview-label">Sådan ser det ud i kalenderen</p><div id="event-preview" class="event-preview" aria-live="polite"></div><p class="footnote">Forhåndsvisningen er privat, mens du skriver.</p></aside></div>${channels()}`;
}
function formEvent(form){const f=Object.fromEntries(new FormData(form));const a=association(f.associationId);return {title:(f.title||'').trim(),associationId:a?.id||null,association:a?.name||(f.association||'').trim(),date:f.date,time:f.time,endDate:f.endDate||'',endTime:f.endTime||'',location:(f.location||'').trim(),description:(f.description||'').trim(),price:(f.price||'').trim(),url:(f.url||'').trim()};}
function eventCard(e){return `<div class="large-date">${e.date?fmt(e.date,{weekday:'long',day:'numeric',month:'long'}):'Dato for arrangementet'}</div><h2>${esc(e.title||'Jeres næste arrangement')}</h2><p>${esc(e.time||'Tidspunkt')} · ${esc(e.location||'Her foregår det')}</p><p>${esc(e.description||'Her står lidt om det, I inviterer til.')}</p>${e.price?`<p>${esc(e.price)}</p>`:''}<div class="association">${esc(e.association||'Jeres forening')}</div>`;}
function updatePreview(){const f=$('#event-form');if(f)$('#event-preview').innerHTML=eventCard(formEvent(f));}
function publish(event,data){const next={...publicData({...event,...data}),status:data.status||'published'};Object.assign(event,next);event.history.push({at:new Date().toISOString(),data:clone(next)});event.pending=null;event.moderationNote='';}
function submitEvent(form){
 const data=formEvent(form),old=db.events.find(e=>e.id===form.dataset.id),direct=isTeb()||(!old?myMemberships().some(m=>m.associationId===data.associationId):canEdit(old));
 const err=$('#event-error');if(!data.title||!data.association||!data.location){err.textContent='Udfyld navn, arrangør og sted.';return;}
 if(data.url&&!/^https?:\/\//i.test(data.url)){err.textContent='Tilmeldingslinket skal starte med https:// eller http://.';return;}
 if(data.endDate&&data.endDate<data.date){err.textContent='Slutdatoen skal være samme dag eller senere end startdatoen.';return;}
 if((!data.endDate||data.endDate===data.date)&&data.endTime&&data.endTime<=data.time){err.textContent='Sluttiden skal ligge efter starttidspunktet.';return;}
 if(old&&!canEdit(old)&&!canGuestEdit(old,form.dataset.key)){err.textContent='Du har ikke adgang til at ændre dette arrangement.';return;}
 const contact=new FormData(form).get('contactEmail')||session?.email;const event=old||{id:uid(),ownerEmail:session?.email||contact,contactEmail:contact,createdAt:new Date().toISOString(),history:[],manageToken:direct?'':uid(),status:'pending',...data};
 if(!old)db.events.push(event);
 if(direct){publish(event,{...data,status:'published'});save();go('kalender/kvittering/'+event.id);toast(old?'Ændringerne er udgivet.':'Arrangementet er nu i kalenderen.');}
 else{event.pending={kind:old?'update':'create',data:{...data,id:event.id,status:'pending'}};event.contactEmail=contact;event.moderationNote='';if(event.status==='rejected')event.status='pending';save();go('kalender/mit/'+event.id+'/'+event.manageToken);toast('Gemt. En mail til TEB er simuleret.');}
}
function renderReceipt(id,key=''){
 const e=db.events.find(v=>v.id===id);if(!e||(!canEdit(e)&&!canGuestEdit(e,key)))return notFound();const pending=e.pending;const data=pending?.data||e;
 const state=pending?'pending':e.status;const title=state==='published'?'Det er med i kalenderen.':state==='cancelled'?'Arrangementet er aflyst.':state==='rejected'?'TEB har sendt en besked.':'Tak. TEB har modtaget det.';
 return `<section class="receipt"><div class="receipt-symbol" aria-hidden="true">${state==='published'?'✓':'↗'}</div>${statusTag(state)}<h1 style="margin-top:18px;font-size:44px">${title}</h1><p class="muted">${pending?(pending.kind==='cancel'?'TEB skal godkende aflysningen. Det nuværende arrangement står fortsat i kalenderen.':e.status==='published'?'Din rettelse afventer TEB. Den nuværende version er stadig offentlig.':'Du kan se status her. Arrangementet bliver offentligt, når TEB har godkendt det.'):'Her kan du se status og opdatere oplysningerne.'}</p>${e.moderationNote?`<div class="info-box"><strong>Besked fra TEB</strong><br>${esc(e.moderationNote)}</div>`:''}<div class="event-preview">${eventCard(data)}</div><div class="actions" style="margin-top:24px">${state==='published'?link('Se i kalenderen','kalender/arrangement/'+e.id,'primary'):''}${e.status!=='cancelled'&&pending?.kind!=='cancel'?link('Ret oplysninger','kalender/ret/'+e.id+(key?'/'+key:'')):''}${e.status==='published'&&!pending?button(canEdit(e)?'Aflys arrangement':'Bed TEB om aflysning','cancel-event',`data-id="${e.id}" data-key="${esc(key)}"`,'danger'):''}</div>${key?`<div class="info-box"><strong>Dit private link</strong><p style="margin-top:8px">Gem linket for at følge status eller rette arrangementet. Alle med linket kan foreslå ændringer.</p>${button('Kopiér mit private link','copy-link','','soft small')}<p class="note" style="margin-top:8px">I den færdige løsning kommer linket også på mail. Her sendes ingen mail.</p></div>`:''}</section>${channels()}`;
}
function renderAccessRequest(){return `<form id="access-form" class="form-panel form-stack" style="max-width:650px"><h3>Få adgang til en forening</h3><label>Dit navn<input name="name" required maxlength="80"></label><label>Din e-mail<input name="email" type="email" value="${esc(session?.email||'')}" required></label><label>Forening<select name="associationId" id="access-association">${db.associations.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}<option value="new">Vores forening mangler på listen</option></select></label><label id="new-association-label" hidden>Foreningens navn<input name="newName" maxlength="100"></label><label>Din rolle i foreningen<input name="note" required maxlength="200" placeholder="Fx formand eller bestyrelsesmedlem"></label><p class="note">TEB kontrollerer din tilknytning, før du får adgang. Det er ikke nok at kende en forenings navn.</p><button class="btn primary" type="submit">Send anmodning til TEB</button></form>`;}
function requestAccess(){openModal('Få din forening med.',renderAccessRequest());}
function login(step='email'){
 if(step==='code'){openModal('Tjek din e-mail.',`<p class="muted">Indtast koden til ${esc(loginEmail)}.</p><div class="mail-preview"><strong>Simuleret mail</strong><p class="note">Der er ikke sendt en rigtig mail. Prøvekoden er:</p><div class="code">123456</div></div><form id="code-form" class="form-stack"><label>Engangskode<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required autofocus></label><p id="login-error" class="form-error" role="alert"></p><button type="submit" class="btn primary">Log ind</button></form>${button('Brug en anden e-mail','login','','small soft')}`);return;}
 openModal('Velkommen tilbage.',`<p class="muted">Log ind med din e-mail. Ingen adgangskode at huske.</p><form id="login-form" class="form-stack"><label>Din e-mail<input type="email" name="email" value="${esc(loginEmail)}" placeholder="dig@forening.dk" required autocomplete="email"></label><button class="btn primary" type="submit">Send engangskode</button></form><p class="footnote">Prøv <strong>anna@forening.example</strong> som foreningsansvarlig eller <strong>teb@prototype.example</strong> som TEB. Andre mails kan anmode om adgang.</p>`);
}
function renderAdmin(tab='pending'){
 if(!isTeb())return loginRequired();let body='';const pending=db.events.filter(e=>e.pending),requests=db.requests.filter(r=>r.status==='pending');
 if(tab==='print')body=`<div class="profile-layout"><form id="edition-form" class="form-panel form-stack"><h2>Lav en printudgave</h2><p class="note">Vælg selv perioden. Kalenderen låser jer ikke til måneder eller kvartaler.</p><div class="form-row"><label>Fra dato<input name="start" type="date" value="${localDate(shownMonth)}" required></label><label>Til dato<input name="end" type="date" value="${localDate(monthEnd(shiftMonth(shownMonth,1)))}" required></label></div><label>Indhold godkendt senest<input name="deadline" type="date" value="${today()}" max="${today()}" required></label><p class="note">Kun den senest offentliggjorte version ved fristen kommer med. Aflysninger før fristen udelades.</p><div id="edition-error" class="form-error" role="alert"></div><button class="btn primary" type="submit">Gennemse printudgave</button></form><aside><h3>Samme indhold, enklere form.</h3><p class="muted">Dato, tid, titel, arrangør og sted sættes automatisk. Du gennemser udgaven, før den gemmes i arkivet.</p><p class="muted">En udgivet plakat ændrer sig ikke, når et arrangement senere bliver rettet.</p><p class="note">Prototypen bruger A3. Endeligt plakatformat aftales senere.</p></aside></div><section class="section" style="margin-top:35px"><h2>Udgivne printkalendere</h2>${db.editions.slice().reverse().map(e=>`<div class="list-row"><div><h3>${esc(editionTitle(e))}</h3><p>${e.events.length} arrangementer · Frist ${fmt(e.deadline)}</p></div>${link('Åbn print','kalender/print/'+e.id,'small')}</div>`).join('')}</section>`;
 else if(tab==='access')body=`<h2>Anmodninger om foreningsadgang</h2><p class="muted">Kontrollér tilknytningen, fx ved at kontakte den kendte formand. Derefter kan du give adgang.</p>${requests.length?requests.map(r=>`<article class="list-row"><div><h3>${esc(r.name)}</h3><p>${esc(r.email)} · ${esc(association(r.associationId)?.name||r.newName)}</p><p>${esc(r.note)}</p></div><div class="actions">${button('Giv adgang','approve-access',`data-id="${r.id}"`,'primary small')}${button('Afvis','reject-access',`data-id="${r.id}"`,'small')}</div></article>`).join(''):'<div class="empty">Ingen afventende anmodninger om adgang.</div>'}<section class="section" style="margin-top:30px"><h2>Foreninger og ansvarlige</h2>${db.associations.map(a=>`<div class="list-row"><div><h3>${esc(a.name)}</h3><p>${db.memberships.filter(m=>m.associationId===a.id&&m.role==='manager').map(m=>esc(m.email)).join(', ')||'Ingen ansvarlig tilknyttet endnu'}</p></div>${button('Administrér adgang','admin-access',`data-association="${a.id}"`,'small')}</div>`).join('')}</section>`;
 else if(tab==='events')body=`<div class="section-heading"><h2>Alle arrangementer</h2>${link('Opret arrangement +','kalender/opret','primary')}</div>${db.events.slice().sort(sortEvents).map(e=>`<article class="list-row"><div>${statusTag(e.status)}<h3 style="margin-top:9px">${esc(e.title)}</h3><p>${fmt(e.date)} · ${esc(e.association)}</p></div><div class="actions">${e.status==='published'?link('Ret','kalender/ret/'+e.id,'small')+button('Aflys','cancel-event',`data-id="${e.id}"`,'small danger'):''}${e.pending?button('Gennemse','review-event',`data-id="${e.id}"`,'small'):''}</div></article>`).join('')}`;
 else body=`<div class="section-heading"><h2>Afventer godkendelse</h2><span class="small muted">${pending.length} indsendelse${pending.length===1?'':'r'}</span></div><p class="muted">Gæsteindsendelser kommer her. Foreninger med godkendt adgang udgiver selv.</p>${pending.length?pending.map(e=>{const d=e.pending.data;return `<article class="list-row"><div><span class="tag pending">${({create:'Nyt arrangement',update:'Rettelse',cancel:'Aflysning'})[e.pending.kind]}</span><h3 style="margin-top:9px">${esc(d.title)}</h3><p>${fmt(d.date)} · ${esc(d.association)}</p><p>Fra ${esc(e.contactEmail)}</p></div>${button('Gennemse','review-event',`data-id="${e.id}"`,'primary small')}</article>`;}).join(''):'<div class="empty">Alt er gennemgået. Der er ingen indsendelser, der venter.</div>'}<div class="info-box">I den færdige løsning får TEB en mail om nye gæsteindsendelser. Her simuleres beskeden ved, at indsendelsen vises i listen.</div>`;
 return pageHero('TEB · administration','Hold overblikket.','Godkend indsendelser, hjælp foreningerne i gang, og lav kalenderen til byen.')+`<nav class="workspace-nav admin-nav" aria-label="TEBs arbejdsområde">${[['pending','Indsendelser · '+pending.length],['events','Arrangementer'],['access','Foreningsadgang · '+requests.length],['print','Printudgaver']].map(([v,n])=>`<a class="${tab===v?'active':''}" href="#forening/teb/${v}">${n}</a>`).join('')}</nav>${body}`;
}
function reviewEvent(id){const e=db.events.find(v=>v.id===id);if(!isTeb()||!e?.pending)return;const d=e.pending.data;openModal(e.pending.kind==='cancel'?'Godkend aflysning':'Gennemse indsendelsen',`<div class="small muted">Fra ${esc(e.contactEmail)}</div><div class="event-preview" style="margin:20px 0">${eventCard(d)}</div>${e.pending.kind==='cancel'?'<p>Godkendelse markerer arrangementet som aflyst i den digitale kalender.</p>':`<label>Ret eventuelt titlen<input id="review-title" value="${esc(d.title)}" maxlength="150"></label><label style="margin-top:16px">Ret eventuelt beskrivelsen<textarea id="review-description" maxlength="1500">${esc(d.description)}</textarea></label>`}<div class="actions" style="margin-top:22px">${button(e.pending.kind==='cancel'?'Godkend aflysning':'Godkend og offentliggør','approve-event',`data-id="${e.id}"`,'primary')}${button('Afvis med besked','reject-event',`data-id="${e.id}"`)}</div>`);}
function snapshot(start,end,deadline){return db.events.flatMap(e=>{const versions=e.history.filter(v=>localDate(new Date(v.at))<=deadline).sort((a,b)=>a.at.localeCompare(b.at));const last=versions.at(-1)?.data;return last&&last.status==='published'&&last.date<=end&&(last.endDate||last.date)>=start?[clone(last)]:[];}).sort(sortEvents);}
function renderPrint(id){const e=id==='preview'?draftEdition:db.editions.find(v=>v.id===id);if(!e||id==='preview'&&!isTeb())return notFound();const groups={};for(const ev of e.events){const k=ev.date.slice(0,7);(groups[k]??=[]).push(ev);}
 return `<section class="print-view"><div class="print-controls"><div><a href="#${id==='preview'?'forening/teb/print':'kalender'}">← ${id==='preview'?'Tilbage til indstillinger':'Til kalenderen'}</a><p class="note">${id==='preview'?'Kladde. Gem udgaven, når du har gennemset den.':'Udgivet prøveudgave. Indholdet er gemt fast.'}</p></div><div class="actions">${id==='preview'?button('Udgiv printudgaven','publish-edition','','primary'):''}${button('Print / gem som PDF','print','','soft')}</div></div><article class="poster" id="print-sheet"><div class="poster-top"><div><div style="font-size:12px;letter-spacing:.15em;margin-bottom:12px">TISTRUP ERHVERVS- OG BORGERFORENING</div><h1>Det sker i<br>Tistrup &amp; Hodde.</h1><p class="poster-period">${esc(editionTitle(e))}</p></div><span class="proof">PRØVEUDGAVE</span></div>${Object.entries(groups).map(([month,evs])=>`<section class="poster-month"><h2>${fmt(month+'-01',{month:'long',year:'numeric'})}</h2>${evs.map(ev=>`<div class="poster-row"><div><strong>${dateOf(ev.date).getDate()}${ev.endDate?' til '+dateOf(ev.endDate).getDate():''}/${dateOf(ev.date).getMonth()+1}</strong><br>${esc(ev.time)}</div><div><strong>${esc(ev.title)}</strong><p>${esc(ev.association)} · ${esc(ev.location)}</p></div></div>`).join('')}</section>`).join('')}${e.events.length?'':'<p>Ingen arrangementer i den valgte periode og før fristen.</p>'}<footer class="poster-footer"><span>Samlet af TEB · ${e.events.length} arrangementer<br>Indhold offentliggjort senest ${fmt(e.deadline,{day:'numeric',month:'long',year:'numeric'})}</span><span>Den digitale kalender har de seneste rettelser.<br>Alle arrangementer her er opdigtede eksempler.</span></footer></article></section>`;
}
function notFound(){return `<section class="not-found"><h1>Her er ikke noget at vise.</h1><p class="muted">Siden findes ikke, eller du har ikke adgang til den.</p>${link('Til kalenderen','kalender','primary')}</section>`;}
function render(){
 const [page,part,id,key]=currentPath();const area=page==='det-sker'?'det-sker':page==='kalender'?'kalender':'forening';
 $$('.nav a').forEach(a=>a.dataset.nav===area?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));
 $('#account-nav').innerHTML=session?`<div class="actions">${link(isTeb()?'TEB':'Min forening',isTeb()?'forening/teb':'forening/min','small')}${button('Log ud','logout','','small soft')}</div>`:button('Log ind','login','','soft');
 const role=!session?'guest':isTeb()?'teb':session.email==='mikkel@forening.example'?'editor':session.email==='anna@forening.example'?'association':'custom';const chooser=$('#demo-role');$('option[value="custom"]',chooser)?.remove();if(role==='custom'){const option=document.createElement('option');option.value='custom';option.textContent='Logget ind · '+session.email;chooser.append(option);}chooser.value=role;
 document.body.classList.toggle('printing',page==='kalender'&&part==='print');
 document.title=({forening:'Forening',kalender:'Kalender','det-sker':'Det sker'})[area]+' · Tistrup & Hodde · TEB prototype';
 let html;
 if(page==='forening')html=part==='profil'?renderProfile(id):part==='min'?renderWorkspace(id||'events'):part==='teb'?renderAdmin(id||'pending'):renderDirectory();
 else if(page==='kalender')html=part==='opret'?renderEventForm():part==='ret'?renderEventForm(id,key):part==='arrangement'?renderEvent(id):part==='mit'?renderReceipt(id,key):part==='kvittering'?renderReceipt(id):part==='print'?renderPrint(id):renderCalendar();
 else if(page==='det-sker')html=renderExternal();else html=notFound();
 $('#main').innerHTML=html;updatePreview();
}
async function copyLink(){const text=location.href;try{await navigator.clipboard.writeText(text);toast('Linket er kopieret.');}catch{openModal('Gem linket',`<p>Markér og kopiér linket.</p><input class="link-input" readonly aria-label="Link til siden" value="${esc(text)}">`);$('.link-input').select();}}
function downloadIcs(e){
 const icsEscape=v=>String(v||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
 const start=e.date.replaceAll('-','')+'T'+e.time.replace(':','')+'00';
 const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//TEB//Standalone prototype//DA','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+e.id+'@prototype.teb','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z'),'DTSTART;TZID=Europe/Copenhagen:'+start];
 if(e.endTime)lines.push('DTEND;TZID=Europe/Copenhagen:'+(e.endDate||e.date).replaceAll('-','')+'T'+e.endTime.replace(':','')+'00');
 lines.push('SUMMARY:'+icsEscape(e.title),'LOCATION:'+icsEscape(e.location),'DESCRIPTION:'+icsEscape(e.description+'\nArrangør: '+e.association),'STATUS:'+(e.status==='cancelled'?'CANCELLED':'CONFIRMED'),'END:VEVENT','END:VCALENDAR');
 const blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tistrup-arrangement.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function adminAccess(id){if(!isTeb())return;const a=association(id);if(!a)return;openModal('Adgang til '+esc(a.name),`<div>${db.memberships.filter(m=>m.associationId===id).map(m=>`<div class="list-row"><div><strong>${esc(m.name||m.email)}</strong><p>${esc(m.email)}<br>${m.role==='manager'?'Ansvarlig':'Redaktør'} · ${m.status==='invited'?'Inviteret':'Aktiv'}</p></div>${button('Fjern','admin-remove-access',`data-email="${esc(m.email)}" data-association="${id}"`,'small danger')}</div>`).join('')||'<p>Ingen personer har adgang endnu.</p>'}</div><form id="admin-member-form" class="form-stack" data-id="${id}" style="margin-top:25px"><h3>Tilknyt en person</h3><label>Navn<input name="name" required maxlength="80"></label><label>E-mail<input name="email" type="email" required></label><label>Adgang<select name="role"><option value="manager">Foreningsansvarlig</option><option value="editor">Redaktør</option></select></label><label class="inline-choice"><input name="checked" type="checkbox" required>Jeg har kontrolleret personens tilknytning</label><button class="btn primary" type="submit">Giv adgang</button></form>`);}
document.addEventListener('click',async ev=>{
 if(ev.target.closest('a.sr-only')){ev.preventDefault();$('#main').focus();return;}
 const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;
 if(action==='close-modal'){closeModal();return;}
 if(action==='login'){if(b.dataset.email)loginEmail=b.dataset.email;login();return;}
 if(action==='logout'){setSession(null);closeModal();go('forening');toast('Du er logget ud.');return;}
 if(action==='request-access'){requestAccess();return;}
 if(action==='help'){openModal('Prøv hele forløbet.',`<ol class="small"><li>Som <strong>besøgende</strong>: Opret et arrangement på Kalender. Det står privat og afventer TEB.</li><li>Vælg <strong>TEB</strong> nederst: Gennemse og godkend indsendelsen. Se den derefter i kalenderen.</li><li>Vælg <strong>Anna</strong>: Ret foreningsprofilen, invitér en redaktør, og udgiv et arrangement direkte.</li><li>Som <strong>TEB</strong>: Vælg Printudgaver, gennemse en periode og udgiv den.</li></ol><p class="note">Du kan også prøve e-mailkode-login. Prøvekoden er 123456. Ingen rigtige mails sendes. Hele prototypen virker uden internet, bortset fra links til andre hjemmesider.</p>`);return;}
 if(action==='reset'){actionConfirm('Start forfra?','Alle ændringer i denne prototype fjernes, og eksempeldata gendannes. Den eksisterende pilot påvirkes ikke.','reset-confirm');return;}
 if(action==='reset-confirm'){db=seed();setSession(null);save();shownMonth=monthStart(new Date());shownWeek=weekStart(new Date());filterText='';filterCategory='';draftEdition=null;closeModal();go('forening');toast('Eksempeldata er gendannet.');return;}
 if(action.startsWith('calendar-')){
  if(action==='calendar-prev'||action==='calendar-next'){const dir=action==='calendar-prev'?-1:1;if(calendarMode==='month')shownMonth=shiftMonth(shownMonth,dir);else shownWeek=addDays(shownWeek,dir*7);}
  if(action==='calendar-today'){shownMonth=monthStart(new Date());shownWeek=weekStart(new Date());}
  if(action==='calendar-week'){calendarMode='week';shownWeek=weekStart(shownMonth.getMonth()===new Date().getMonth()&&shownMonth.getFullYear()===new Date().getFullYear()?new Date():shownMonth);}
  if(action==='calendar-month'){if(calendarMode==='week')shownMonth=monthStart(shownWeek);calendarMode='month';}
  $('#calendar-content').innerHTML=calendarContent();return;
 }
 if(action==='open-event'){go('kalender/arrangement/'+id);return;}
 if(action==='copy-link'){await copyLink();return;}
 if(action==='download-ics'){const e=db.events.find(x=>x.id===id);if(e&&['published','cancelled'].includes(e.status))downloadIcs(e);return;}
 if(action==='channel'){
  const channel=b.dataset.channel;const info={
   'Omdeling og flyers':['Flyers i postkasserne','Her kan I finde lokale omdelere, aftale format og frist og få et tilbud. I prototypen er der endnu ingen aftale med en omdeler.'],
   'Byportaler og infoskærme':['Byportaler og infoskærme','Her samler vi kontakt, billedformat og indsendelsesfrist til hver udbyder. TEB administrerer ikke de eksterne skærme.'],
   'Plakater og opslag':['Opslag rundt i byen','Lav en enkel plakat med dato, sted og tilmelding. Her kommer en oversigt over opslagstavler og aftalte steder, herunder eventuelle lygtepæle. Tjek aftalen med ejeren, før I hænger op.'],
   'Medier og Facebook':['Tip de lokale medier','Send en kort tekst med hvad, hvor og hvornår, og gerne et billede. Hvert medie beslutter selv, hvad det bringer.']
  }[channel];openModal(esc(info[0]),`<p>${esc(info[1])}</p>${channel==='Medier og Facebook'?`<p>${external('Tistrup Nyt','https://tistrupnyt.dk/')}</p><p>${external('Tistrupnews','https://www.tistrupnews.dk/')}</p>`:'<div class="info-box">Kontaktoplysninger og konkrete udbydere afventer TEBs aftaler. Der bestilles eller sendes ikke noget her.</div>'}`);return;
 }
 if(action==='cancel-event'){
  const e=db.events.find(v=>v.id===id);if(!e||e.status!=='published'||(!canEdit(e)&&!canGuestEdit(e,b.dataset.key)))return;
  const direct=canEdit(e);actionConfirm(direct?'Aflys arrangementet?':'Send aflysning til TEB?',direct?'Arrangementet bliver markeret som aflyst i den digitale kalender. Allerede udgivne print ændres ikke.':'Arrangementet er stadig offentligt, indtil TEB har godkendt aflysningen.','confirm-cancel',`data-id="${id}" data-key="${esc(b.dataset.key||'')}"`);return;
 }
 if(action==='confirm-cancel'){
  const e=db.events.find(v=>v.id===id);if(!e||e.status!=='published')return;const key=b.dataset.key;
  if(canEdit(e)){publish(e,{...publicData(e),status:'cancelled'});save();closeModal();render();toast('Arrangementet er markeret som aflyst.');}
  else if(canGuestEdit(e,key)){e.pending={kind:'cancel',data:publicData(e)};save();closeModal();go('kalender/mit/'+id+'/'+key);toast('Aflysningen er sendt til TEB i prototypen.');}return;
 }
 if(action==='review-event'){reviewEvent(id);return;}
 if(action==='approve-event'){
  const e=db.events.find(v=>v.id===id);if(!isTeb()||!e?.pending)return;const d=clone(e.pending.data);if(e.pending.kind!=='cancel'){d.title=$('#review-title').value.trim();d.description=$('#review-description').value.trim();if(!d.title){$('#review-title').focus();toast('Arrangementet skal have et navn.');return;}}
  d.status=e.pending.kind==='cancel'?'cancelled':'published';publish(e,d);save();closeModal();render();toast(d.status==='cancelled'?'Aflysningen er godkendt.':'Godkendt. Arrangementet er nu offentligt.');return;
 }
 if(action==='reject-event'){
  if(!isTeb())return;openModal('Send en besked til afsenderen',`<form id="reject-form" class="form-stack" data-id="${id}"><label>Hvorfor kan det ikke godkendes?<textarea name="note" maxlength="800" required placeholder="Skriv gerne, hvad afsenderen kan rette."></textarea></label><button class="btn primary" type="submit">Afvis og gem besked</button><p class="note">En besked til afsenderen simuleres. En tidligere offentlig version bevares.</p></form>`);return;
 }
 if(action==='approve-access'){
  const req=db.requests.find(r=>r.id===id);if(!isTeb()||!req)return;openModal('Giv foreningsadgang',`<p><strong>${esc(req.name)}</strong><br>${esc(req.email)}<br>${esc(association(req.associationId)?.name||req.newName)}</p><form id="approve-access-form" class="form-stack" data-id="${id}"><label class="inline-choice"><input type="checkbox" name="verified" required>Jeg har kontrolleret personens tilknytning til foreningen</label><button class="btn primary" type="submit">Godkend som foreningsansvarlig</button></form>`);return;
 }
 if(action==='reject-access'){if(!isTeb())return;const r=db.requests.find(v=>v.id===id);if(r){r.status='rejected';save();render();toast('Anmodningen er afvist i prototypen.');}return;}
 if(action==='admin-access'){adminAccess(b.dataset.association);return;}
 if(action==='remove-access'||action==='admin-remove-access'){
  const aid=b.dataset.association,email=b.dataset.email;if(!canManageAssociation(aid))return;
  actionConfirm('Fjern adgangen?',`${esc(email)} vil ikke længere kunne redigere eller udgive for foreningen.`,'confirm-remove-access',`data-association="${aid}" data-email="${esc(email)}"`);return;
 }
 if(action==='confirm-remove-access'){
  const aid=b.dataset.association,email=b.dataset.email,target=db.memberships.find(m=>m.associationId===aid&&m.email===email);
  if(!target||!canManageAssociation(aid)||!isTeb()&&(email===session?.email||target.role==='manager'))return;
  db.memberships=db.memberships.filter(m=>!(m.associationId===aid&&m.email===email));save();closeModal();render();toast('Adgangen er fjernet.');return;
 }
 if(action==='publish-edition'){if(!isTeb()||!draftEdition)return;const edition={...clone(draftEdition),id:uid(),createdAt:new Date().toISOString()};db.editions.push(edition);save();draftEdition=null;go('kalender/print/'+edition.id);toast('Printudgaven er gemt i arkivet.');return;}
 if(action==='print'){window.print();return;}
});
document.addEventListener('input',ev=>{
 if(ev.target.closest('#event-form'))updatePreview();
 if(ev.target.id==='association-search'){filterText=ev.target.value;$('#association-results').innerHTML=directoryCards();}
});
document.addEventListener('change',ev=>{
 if(ev.target.id==='event-association'&&$('#other-organizer'))$('#other-organizer').hidden=!!ev.target.value;
 if(ev.target.id==='association-category'){filterCategory=ev.target.value;$('#association-results').innerHTML=directoryCards();}
 if(ev.target.id==='access-association'){const show=ev.target.value==='new';$('#new-association-label').hidden=!show;$('[name=newName]',$('#access-form')).required=show;}
 if(ev.target.id==='workspace-association'){try{localStorage.setItem('teb-demo-selected-association',JSON.stringify(ev.target.value));}catch{}render();}
 if(ev.target.id==='demo-role'){
  const choice=ev.target.value;setSession(choice==='guest'?null:{email:({association:'anna@forening.example',editor:'mikkel@forening.example',teb:'teb@prototype.example'})[choice]});closeModal();go(choice==='teb'?'forening/teb':choice==='guest'?'forening':'forening/min');toast(choice==='guest'?'Du prøver som besøgende.':choice==='teb'?'Du prøver som TEB.':'Du prøver som '+(choice==='editor'?'redaktør':'foreningsansvarlig')+'.');
 }
});
document.addEventListener('submit',ev=>{
 const f=ev.target;if(!['event-form','profile-form','invite-form','access-form','login-form','code-form','reject-form','edition-form','approve-access-form','admin-member-form'].includes(f.id))return;ev.preventDefault();const data=Object.fromEntries(new FormData(f));
 if(f.id==='event-form'){submitEvent(f);return;}
 if(f.id==='login-form'){loginEmail=data.email.trim().toLowerCase();loginRequestedAt=Date.now();login('code');return;}
 if(f.id==='code-form'){
  if(data.code!=='123456'){$('#login-error').textContent='Koden er ikke korrekt. Brug prøvekoden 123456.';return;}
  if(Date.now()-loginRequestedAt>600000){$('#login-error').textContent='Koden er udløbet. Bed om en ny kode.';return;}
  db.memberships.filter(m=>m.email===loginEmail&&m.status==='invited').forEach(m=>m.status='active');save();setSession({email:loginEmail});closeModal();go(loginEmail==='teb@prototype.example'?'forening/teb':'forening/min');toast('Du er logget ind.');return;
 }
 if(f.id==='profile-form'){
  const a=association(f.dataset.id);if(!a||!myMemberships().some(m=>m.associationId===a.id)&&!isTeb())return;
  if(data.website&&!/^https?:\/\//i.test(data.website)){toast('Hjemmesiden skal starte med https:// eller http://.');return;}
  for(const field of ['name','description','chair','category','email','phone','place','website'])a[field]=(data[field]||'').trim();
  for(const e of db.events.filter(e=>e.associationId===a.id))e.association=a.name;
  save();toast('Oplysningerne er gemt på den offentlige profil.');return;
 }
 if(f.id==='invite-form'||f.id==='admin-member-form'){
  const aid=f.dataset.id;if(!canManageAssociation(aid))return;const email=data.email.trim().toLowerCase();
  if(db.memberships.some(m=>m.email===email&&m.associationId===aid)){toast('Personen har allerede adgang eller en invitation.');return;}
  const admin=f.id==='admin-member-form';db.memberships.push({email,name:data.name.trim(),associationId:aid,role:admin?data.role:'editor',status:admin?'active':'invited'});save();
  if(admin){closeModal();render();toast('Personen har fået adgang i prototypen.');}
  else{render();openModal('Invitationen er klar.',`<p>En invitation til <strong>${esc(email)}</strong> er simuleret.</p><p class="muted">Prøv at logge ind med adressen og prøvekoden for at acceptere invitationen.</p>${button('Prøv personens login','login',`data-email="${esc(email)}"`,'primary')}`);}return;
 }
 if(f.id==='access-form'){
  const email=data.email.trim().toLowerCase();if(db.requests.some(r=>r.email===email&&r.associationId===data.associationId&&r.status==='pending')){toast('Der ligger allerede en anmodning hos TEB.');return;}
  if(data.associationId==='new'&&!data.newName.trim())return;
  db.requests.push({id:uid(),...data,email,status:'pending'});save();closeModal();openModal('TEB har fået din anmodning.',`<p>TEB skal kontrollere din tilknytning, før du får adgang til foreningen.</p><p class="note">I prototypen ligger anmodningen nu under TEB → Foreningsadgang. Ingen mail er sendt.</p>${button('Luk','close-modal','','primary')}`);return;
 }
 if(f.id==='approve-access-form'){
  if(!isTeb()||!data.verified)return;const r=db.requests.find(v=>v.id===f.dataset.id);if(!r||r.status!=='pending')return;
  let aid=r.associationId;if(aid==='new'){aid=uid();db.associations.push({id:aid,name:r.newName.trim(),category:'Andet',initials:r.newName.trim().split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase(),description:'Foreningen er ny i oversigten. Flere oplysninger er på vej.',chair:r.name,email:r.email,phone:'',website:'',place:''});}
  const existing=db.memberships.find(m=>m.email===r.email&&m.associationId===aid);if(existing){existing.status='active';existing.role='manager';}else db.memberships.push({email:r.email,name:r.name,associationId:aid,role:'manager',status:'active'});
  r.status='approved';save();closeModal();render();toast('Foreningsadgangen er godkendt.');return;
 }
 if(f.id==='reject-form'){
  const e=db.events.find(v=>v.id===f.dataset.id);if(!isTeb()||!e?.pending||!data.note.trim())return;
  if(e.status!=='published'&&e.status!=='cancelled')e.status='rejected';e.pending=null;e.moderationNote=data.note.trim();save();closeModal();render();toast('Afvist. Beskeden kan ses på afsenderens private side.');return;
 }
 if(f.id==='edition-form'){
  if(!isTeb())return;const err=$('#edition-error');if(data.start>data.end){err.textContent='Slutdatoen skal være samme dag eller senere end startdatoen.';return;}if(data.deadline>today()){err.textContent='Vælg en frist i dag eller tidligere.';return;}
  draftEdition={start:data.start,end:data.end,deadline:data.deadline,events:snapshot(data.start,data.end,data.deadline)};
  if(!draftEdition.events.length){err.textContent='Ingen offentliggjorte arrangementer passer til perioden og fristen.';draftEdition=null;return;}
  go('kalender/print/preview');return;
 }
});
document.addEventListener('keydown',ev=>{
 const modal=$('.modal');if(!modal)return;if(ev.key==='Escape'){closeModal();return;}
 if(ev.key==='Tab'){const focusable=$$('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled)',modal).filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}
});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
save();render();
})();
